from __future__ import annotations

import json
import re
import unicodedata


_NUMBER_WORDS = {
    "zero": "0",
    "one": "1",
    "two": "2",
    "three": "3",
    "four": "4",
    "five": "5",
    "six": "6",
    "seven": "7",
    "eight": "8",
    "nine": "9",
    "ten": "10",
    "eleven": "11",
    "twelve": "12",
}

_FIXED_EQUIVALENTS = {
    "automobile": "car",
    "bike": "bicycle",
    "cellphone": "cell phone",
    "cell phone": "phone",
    "motorbike": "motorcycle",
    "tv": "television",
    "yeah": "yes",
    "yep": "yes",
    "nope": "no",
}


def extract_answer(raw_text: str) -> str | None:
    value = raw_text.strip()
    if not value:
        return None
    try:
        parsed = json.loads(value)
    except json.JSONDecodeError:
        start, end = value.find("{"), value.rfind("}")
        if start < 0 or end <= start:
            return value
        try:
            parsed = json.loads(value[start : end + 1])
        except json.JSONDecodeError:
            return value
    if isinstance(parsed, dict) and isinstance(parsed.get("answer"), (str, int, float, bool)):
        return str(parsed["answer"])
    return value


def normalize_answer(value: str, category: str) -> str:
    normalized = unicodedata.normalize("NFKC", value).strip().casefold()
    normalized = normalized.strip(" \t\r\n\"'“”‘’")
    normalized = re.sub(r"\s+", " ", normalized)
    if category == "OCR":
        return normalized
    normalized = re.sub(r"[^\w\s-]", " ", normalized, flags=re.UNICODE)
    normalized = re.sub(r"\s+", " ", normalized).strip()
    normalized = _NUMBER_WORDS.get(normalized, normalized)
    return _FIXED_EQUIVALENTS.get(normalized, normalized)


def score_answer(
    answer: str | None, accepted_answers: list[str], category: str
) -> tuple[str | None, bool]:
    if answer is None:
        return None, False
    normalized = normalize_answer(answer, category)
    accepted = {normalize_answer(item, category) for item in accepted_answers}
    return normalized, normalized in accepted
